const libraryBatchFour = [
  { file: "iiit-arts-islamic-civilization", pdf: "iiit-arts-islamic-civilization.pdf", cover: "iiit-arts-islamic-civilization-cover.jpg", title: "The Arts of Islamic Civilization", author: "Ismail Raji al-Faruqi", publisher: "International Institute of Islamic Thought", year: "2013", isbn: "978-1-56564-893-7", language: "English", category: "Islamic Civilisation", pages: "34", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/the-arts-of-islamic-civilization/", description: "This concise study relates Islamic artistic expression to the Qur'anic worldview. Al-Faruqi considers how tawhid informs visual form, pattern, space, and sound, and explains why the arts of Muslim societies should be read as cultural and aesthetic practices shaped by religious ideas. It is an accessible introduction to a foundational question in Islamic art history.", citation: "al-Faruqi, Ismail Raji. The Arts of Islamic Civilization. International Institute of Islamic Thought, 2013." },
  { file: "iiit-quranic-terminology", pdf: "iiit-quranic-terminology.pdf", cover: "iiit-quranic-terminology-cover.jpg", title: "Qur'anic Terminology: A Linguistic and Semantic Analysis", author: "Balil Abd Al-Karim", publisher: "International Institute of Islamic Thought", year: "2017", isbn: "978-1-56564-874-6", language: "English", category: "Qur'anic Studies", pages: "190", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/quranic-terminology-a-linguistic-and-semantic-analysis/", description: "A linguistic and semantic investigation of terms used in the Qur'an. The book approaches Qur'anic vocabulary through its Arabic usage and conceptual relationships, helping readers see how individual words function within wider patterns of meaning. It is particularly useful for students interested in the language of the Qur'an and methods of close textual interpretation.", citation: "Abd Al-Karim, Balil. Qur'anic Terminology: A Linguistic and Semantic Analysis. International Institute of Islamic Thought, 2017." },
  { file: "iiit-thematic-commentary-quran", pdf: "iiit-thematic-commentary-quran.pdf", cover: "iiit-thematic-commentary-quran-cover.jpg", title: "A Thematic Commentary on the Qur'an", author: "Shaykh Muhammad Al-Ghazali", publisher: "International Institute of Islamic Thought", year: "2000", isbn: "978-1-56564-502-8", language: "English", category: "Qur'anic Studies", pages: "816", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/a-thematic-commentary-on-the-quran/", description: "Muhammad al-Ghazali's commentary reads the Qur'an through its recurring ethical, social, and spiritual concerns. Rather than treating each verse in isolation, it draws connections across surahs and situates passages within their broader arguments. The English edition offers a substantial resource for readers seeking a thematic approach to Qur'anic interpretation and its treatment of contemporary moral questions.", citation: "Al-Ghazali, Muhammad. A Thematic Commentary on the Qur'an. International Institute of Islamic Thought, 2000." },
  { file: "iiit-quranic-worldview", pdf: "iiit-quranic-worldview.pdf", cover: "iiit-quranic-worldview-cover.jpg", title: "The Qur'anic Worldview: A Springboard for Cultural Reform", author: "AbdulHamid AbuSulayman", publisher: "International Institute of Islamic Thought", year: "2013", isbn: "978-1-56564-780-0", language: "English", category: "Qur'anic Studies", pages: "28", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/the-quranic-worldview/", description: "AbuSulayman outlines a Qur'an-centred framework for cultural renewal. He focuses on the relationship between revelation, reason, moral responsibility, and social action, arguing that a coherent worldview is necessary for reform. This short book introduces key themes in modern Islamic thought while remaining rooted in the Qur'an's ethical and intellectual orientation.", citation: "AbuSulayman, AbdulHamid. The Qur'anic Worldview: A Springboard for Cultural Reform. International Institute of Islamic Thought, 2013." },
  { file: "iiit-foundation-knowledge", pdf: "iiit-foundation-knowledge.pdf", cover: "iiit-foundation-knowledge-cover.jpg", title: "The Foundation of Knowledge: A Comparative Study in Islamic and Western Methods of Inquiry", author: "Louay Safi", publisher: "International Institute of Islamic Thought", year: "2014", isbn: "978-1-56564-898-2", language: "English", category: "Islamic Thought", pages: "216", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/the-foundation-of-knowledge/", description: "Louay Safi compares the intellectual premises and methods of inquiry associated with Islamic and Western traditions. The study examines revelation, reason, observation, and historical experience as sources of knowledge, then considers their methodological implications. It is a focused contribution to debates about epistemology, social science, and the renewal of Islamic intellectual practice.", citation: "Safi, Louay. The Foundation of Knowledge: A Comparative Study in Islamic and Western Methods of Inquiry. International Institute of Islamic Thought, 2014." },
  { file: "iiit-source-methodology-islamic-jurisprudence", pdf: "iiit-source-methodology-islamic-jurisprudence.pdf", cover: "iiit-source-methodology-islamic-jurisprudence-cover.jpg", title: "Source Methodology in Islamic Jurisprudence", subtitle: "Usul al-Fiqh al-Islami", author: "Taha Jabir Al-Alwani", publisher: "International Institute of Islamic Thought", year: "2003", isbn: "978-1-56564-882-1", language: "English", category: "Islamic Jurisprudence", pages: "96", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/source-methodology-in-islamic-jurisprudence/", description: "This introduction examines the sources and methodological questions of usul al-fiqh. Al-Alwani discusses the Qur'an, Sunnah, consensus, reasoning, and the relationship between legal method and changing circumstances. The work is suited to readers who want a concise scholarly overview of how jurists have approached the derivation and interpretation of Islamic legal rulings.", citation: "Al-Alwani, Taha Jabir. Source Methodology in Islamic Jurisprudence: Usul al-Fiqh al-Islami. International Institute of Islamic Thought, 2003." },
  { file: "iiit-islamic-thought-reform", pdf: "iiit-islamic-thought-reform.pdf", cover: "iiit-islamic-thought-reform-cover.jpg", title: "Islamic Thought: An Approach to Reform", author: "Taha Jabir Al-Alwani", publisher: "International Institute of Islamic Thought", year: "2006", isbn: "978-1-56564-548-6", language: "English", category: "Islamic Thought", pages: "192", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/islamic-thought-an-approach-to-reform/", description: "Al-Alwani addresses questions of reform in modern Islamic thought through the disciplines that shape interpretation, education, and public life. The book considers inherited modes of reasoning alongside contemporary intellectual challenges, with emphasis on a principled engagement with revelation and reality. It offers a sustained account of reform as a methodological rather than merely political undertaking.", citation: "Al-Alwani, Taha Jabir. Islamic Thought: An Approach to Reform. International Institute of Islamic Thought, 2006." },
  { file: "iiit-quran-normative-pluralism", pdf: "iiit-quran-normative-pluralism.pdf", cover: "iiit-quran-normative-pluralism-cover.jpg", title: "The Qur'an and Normative Religious Pluralism", subtitle: "A Thematic Study of the Qur'an", author: "Arif Kemil Abdullah", publisher: "International Institute of Islamic Thought", year: "2014", isbn: "978-1-56564-777-0", language: "English", category: "Qur'anic Studies", pages: "316", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/the-quran-and-normative-religious-pluralism/", description: "A thematic study of Qur'anic passages concerned with religious difference, human diversity, and relations among communities. Abdullah considers the interpretive principles that shape readings of these verses and asks how they inform a normative account of pluralism. The book provides a detailed resource for Qur'anic studies, theology, and contemporary discussions of interreligious coexistence.", citation: "Abdullah, Arif Kemil. The Qur'an and Normative Religious Pluralism: A Thematic Study of the Qur'an. International Institute of Islamic Thought, 2014." },
  { file: "iiit-al-shura-quranic-consultation", pdf: "iiit-al-shura-quranic-consultation.pdf", cover: "iiit-al-shura-quranic-consultation-cover.jpg", title: "Al-Shura: The Qur'anic Principle of Consultation", author: "Ahmad Al-Raysuni", publisher: "International Institute of Islamic Thought", isbn: "978-1-56564-504-2", language: "English", category: "Qur'anic Studies", pages: "206", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/al-shura-the-quranic-principle-of-consultation/", description: "Ahmad al-Raysuni studies shura as a Qur'anic principle and a concept in Islamic political and legal thought. The book examines relevant texts, historical interpretations, and the role of consultation in collective decision-making. It gives readers a careful grounding in the term's intellectual history and its continuing importance in discussions of governance and public ethics.", citation: "Al-Raysuni, Ahmad. Al-Shura: The Qur'anic Principle of Consultation. International Institute of Islamic Thought." },
  { file: "iiit-where-east-meets-west", pdf: "iiit-where-east-meets-west.pdf", cover: "iiit-where-east-meets-west-cover.jpg", title: "Where East Meets West", subtitle: "Appropriating the Islamic Encounter for a Spiritual-Cultural Revival", author: "Mona Abul-Fadl", publisher: "International Institute of Islamic Thought", year: "2010", isbn: "978-1-56564-796-1", language: "English", category: "Muslim Intellectual History", pages: "111", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/%e2%80%8bwhere-east-meets-west-appropriating-the-islamic-encounter-for-a-spiritual-cultural-revival/", description: "Mona Abul-Fadl reflects on encounters between Islamic and Western intellectual traditions and their implications for cultural renewal. She considers questions of civilization, knowledge, and spiritual orientation without reducing the relationship to simple opposition. The essays offer a historically informed perspective on cross-cultural exchange and the resources Islamic thought can bring to contemporary intellectual life.", citation: "Abul-Fadl, Mona. Where East Meets West: Appropriating the Islamic Encounter for a Spiritual-Cultural Revival. International Institute of Islamic Thought, 2010." },
  { file: "iiit-apostates-islam-freedom-faith", pdf: "iiit-apostates-islam-freedom-faith.pdf", cover: "iiit-apostates-islam-freedom-faith-cover.png", title: "Apostates, Islam & Freedom of Faith", subtitle: "Change of Conviction vs. Change of Allegiance", author: "AbdulHamid AbuSulayman", publisher: "International Institute of Islamic Thought", isbn: "978-1-56564-509-7", language: "English", category: "Islamic Thought", pages: "42", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/apostates-islam-freedom-of-faith-change-of-conviction-vs-change-%e2%80%8bof-%e2%80%8ballegiance-occasional-paper/", description: "This brief study distinguishes a personal change of religious conviction from political betrayal in discussions of apostasy. AbuSulayman reviews the concepts and historical assumptions that have shaped the debate, then frames freedom of faith as a matter requiring careful textual and contextual analysis. It is a concise source for the modern Islamic legal and ethical discussion.", citation: "AbuSulayman, AbdulHamid. Apostates, Islam & Freedom of Faith: Change of Conviction vs. Change of Allegiance. International Institute of Islamic Thought." },
  { file: "iiit-ifta-fatwa-muslim-world", pdf: "iiit-ifta-fatwa-muslim-world.pdf", cover: "iiit-ifta-fatwa-muslim-world-cover.jpg", title: "Ifta' and Fatwa in the Muslim World and the West", author: "Zulfiqar Ali Shah", publisher: "International Institute of Islamic Thought", year: "2014", isbn: "978-1-56564-538-7", language: "English", category: "Hadith and Islamic Law", pages: "204", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/ifta-and-fatwa-in-the-muslim-world-and-the-west/", description: "Zulfiqar Ali Shah examines ifta, the practice of issuing legal opinions, in both Muslim-majority and Western settings. The book discusses the authority of muftis, the methods and institutions of fatwa, and the challenges created by migration and minority contexts. It offers a comparative account of an important practice in contemporary Islamic legal life.", citation: "Shah, Zulfiqar Ali. Ifta' and Fatwa in the Muslim World and the West. International Institute of Islamic Thought, 2014." },
  { file: "iiit-islam-economic-development", pdf: "iiit-islam-economic-development.pdf", cover: "iiit-islam-economic-development-cover.jpg", title: "Islam and Economic Development", subtitle: "A Strategy for Development with Justice and Stability", author: "Muhammad Umer Chapra", publisher: "International Institute of Islamic Thought", year: "1993", isbn: "979-8-89193-204-3", language: "English", category: "Islamic Civilisation", pages: "186", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/islam-and-economic-development/", description: "Muhammad Umer Chapra sets out an Islamic approach to economic development that treats justice, moral responsibility, and social stability as integral rather than secondary concerns. He connects development policy to the ethical aims of Islam and considers institutional conditions for equitable growth. The book remains a useful reference for Islamic economics and modern Muslim intellectual history.", citation: "Chapra, Muhammad Umer. Islam and Economic Development: A Strategy for Development with Justice and Stability. International Institute of Islamic Thought, 1993." },
  { file: "iiit-issues-contemporary-islamic-thought", pdf: "iiit-issues-contemporary-islamic-thought.pdf", cover: "iiit-issues-contemporary-islamic-thought-cover.jpg", title: "Issues in Contemporary Islamic Thought", author: "Taha Jabir Al-Alwani", publisher: "International Institute of Islamic Thought", year: "2005", isbn: "978-1-56564-549-3", language: "English", category: "Islamic Thought", pages: "316", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/issues-in-contemporary-islamic-thought/", description: "This collection addresses major questions confronting modern Islamic thought, including methodology, legal reasoning, education, and the relationship between tradition and contemporary reality. Al-Alwani argues for intellectual renewal grounded in the Qur'an and Sunnah while attentive to changing social conditions. Its essays provide a broad entry point into debates over reform and Muslim public life.", citation: "Al-Alwani, Taha Jabir. Issues in Contemporary Islamic Thought. International Institute of Islamic Thought, 2005." },
  { file: "iiit-maqasid-ijtihad-civilization-renewal", pdf: "iiit-maqasid-ijtihad-civilization-renewal.pdf", cover: "iiit-maqasid-ijtihad-civilization-renewal-cover.jpg", title: "Maqasid Al-Shari'ah, Ijtihad and Civilization Renewal", author: "Mohammad Hashim Kamali", publisher: "International Institute of Islamic Thought", year: "2012", isbn: "978-1-56564-494-6", language: "English", category: "Islamic Jurisprudence", pages: "60", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/maqasid-al-shariah-ijtihad-and-civilization-renewal/", description: "Mohammad Hashim Kamali explains the relationship between maqasid al-shari'ah, ijtihad, and renewal in Muslim societies. He introduces the higher objectives of Islamic law and considers how purposive reasoning can guide contemporary legal and ethical reflection. This compact study is appropriate for readers seeking an academically grounded introduction to a central framework in modern Islamic jurisprudence.", citation: "Kamali, Mohammad Hashim. Maqasid Al-Shari'ah, Ijtihad and Civilization Renewal. International Institute of Islamic Thought, 2012." },
  { file: "iiit-variant-readings-quran", pdf: "iiit-variant-readings-quran.pdf", cover: "iiit-variant-readings-quran-cover.jpg", title: "Variant Readings of the Qur'an", subtitle: "A Critical Study of Their Historical and Linguistic Origins", author: "Ahmad Ali Al-Imam", publisher: "International Institute of Islamic Thought", year: "2006", isbn: "978-1-56564-795-4", language: "English", category: "Qur'anic Studies", pages: "188", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/variant-readings-of-the-quran-a-critical-study-of-their-historical-%e2%80%8band-linguistic-origins%e2%80%8b/", description: "Ahmad Ali al-Imam investigates the historical and linguistic origins of variant Qur'anic readings. The study introduces the transmission and classification of readings, then evaluates questions raised by their linguistic forms and historical setting. It provides an accessible scholarly treatment of qira'at for students of Qur'anic studies, Arabic linguistics, and the textual history of Islam.", citation: "Al-Imam, Ahmad Ali. Variant Readings of the Qur'an: A Critical Study of Their Historical and Linguistic Origins. International Institute of Islamic Thought, 2006." },
  { file: "iiit-islamic-vision-development-maqasid", pdf: "iiit-islamic-vision-development-maqasid.pdf", cover: "iiit-islamic-vision-development-maqasid-cover.jpg", title: "The Islamic Vision of Development in the Light of Maqasid al-Shari'ah", author: "Muhammad Umer Chapra", publisher: "International Institute of Islamic Thought", year: "2008", isbn: "979-8-89193-203-6", language: "English", category: "Islamic Thought", pages: "56", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/the-islamic-vision-of-development-in-the-light-of-maqasid-al-shariah/", description: "Chapra links development to the maqasid al-shari'ah, arguing that material progress must be assessed alongside moral, social, and human aims. He outlines an Islamic vision of development concerned with justice, dignity, family, knowledge, and good governance. The book offers a compact framework for connecting Islamic ethical thought with policy and development studies.", citation: "Chapra, Muhammad Umer. The Islamic Vision of Development in the Light of Maqasid al-Shari'ah. International Institute of Islamic Thought, 2008." },
  { file: "iiit-parameters-halal-haram", pdf: "iiit-parameters-halal-haram.pdf", cover: "iiit-parameters-halal-haram-cover.jpg", title: "The Parameters of Halal and Haram in Shariah and the Halal Industry", author: "Mohammad Hashim Kamali", publisher: "International Institute of Islamic Thought", year: "2013", isbn: "978-1-56564-776-3", language: "English", category: "Islamic Jurisprudence", pages: "66", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/the-parameters-of-halal-and-haram-in-shariah-and-the-halal-industry-occasional-papers-series-23/", description: "This study explains the legal and ethical categories of halal and haram and considers their application in the contemporary halal industry. Kamali addresses principles of interpretation, consumer practice, regulation, and certification without reducing the discussion to commercial labels. It is a concise guide to the jurisprudential foundations that inform current debates about halal standards.", citation: "Kamali, Mohammad Hashim. The Parameters of Halal and Haram in Shariah and the Halal Industry. International Institute of Islamic Thought, 2013." },
  { file: "iiit-fiqh-minorities", pdf: "iiit-fiqh-minorities.pdf", cover: "iiit-fiqh-minorities-cover.jpg", title: "Towards a Fiqh for Minorities", subtitle: "Some Basic Reflections", author: "Taha Jabir Al-Alwani", publisher: "International Institute of Islamic Thought", year: "2010", isbn: "978-1-56564-790-9", language: "English", category: "Islamic Jurisprudence", pages: "70", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/towards-a-fiqh-for-minorities-some-basic-reflections-2/", description: "Al-Alwani considers the legal and ethical questions faced by Muslim minorities living outside Muslim-majority societies. The book discusses context, citizenship, social participation, and the methods needed for responsible juristic reasoning. It is a foundational modern contribution to the discussion of fiqh al-aqalliyyat and the adaptation of legal thought to minority settings.", citation: "Al-Alwani, Taha Jabir. Towards a Fiqh for Minorities: Some Basic Reflections. International Institute of Islamic Thought, 2010." },
  { file: "iiit-sources-scientific-knowledge", pdf: "iiit-sources-scientific-knowledge.pdf", cover: "iiit-sources-scientific-knowledge-cover.jpg", title: "Sources of Scientific Knowledge", subtitle: "The Geological Concept of Mountains in the Qur'an", author: "Z. R. El-Naggar", publisher: "International Institute of Islamic Thought", year: "1991", isbn: "978-1-56564-067-2", language: "English", category: "Qur'anic Studies", pages: "100", access: "Publisher-designated open access", sourceUrl: "https://iiit.org/en/book/sources-of-scientific-knowledge/", description: "Z. R. El-Naggar examines Qur'anic references to mountains alongside geological concepts and scientific interpretation. The book forms part of a wider modern discussion about knowledge, scripture, and the natural world in Muslim intellectual discourse. It is included as a historical source for the study of twentieth-century Qur'anic interpretation and science-oriented commentary.", citation: "El-Naggar, Z. R. Sources of Scientific Knowledge: The Geological Concept of Mountains in the Qur'an. International Institute of Islamic Thought, 1991." }
];

