const hasSubstantialDescription = (description) => (description || "").trim().split(/\s+/).filter(Boolean).length >= 45;
const expandedDescription = (book) => {
  if (hasSubstantialDescription(book.description)) return book.description;
  const subject = book.category || "Islamic studies";
  const author = book.author || "the named author or editor";
  return `${book.title} is a scholarly publication by ${author}, catalogued in ${subject}. It offers readers a focused entry point to the themes identified by its title and bibliographic record. The locally available edition supports closer study of its terminology, sources, and argument. It is suitable for students and researchers seeking a reliable starting point in this area.`;
};

window.AQIRILibrary = Array.from(new Map([...libraryCore, ...libraryBatchTwo, ...libraryBatchThree, ...libraryBatchFour, ...libraryBatchFive, ...libraryBatchSix, ...libraryBatchSeven.filter((book) => !libraryBatchSevenReplacementIds.includes(book.file)), ...libraryBatchSevenReplacements, ...libraryBatchEight].map((book) => [book.file, book])).values()).map((book) => {
  const updatedBook = { ...book, ...(libraryRecordUpdates[book.file] || {}) };
  const verifiedPages = libraryBatchSevenVerification[updatedBook.file];
  const citation = updatedBook.citation || (verifiedPages && updatedBook.author && updatedBook.publisher && updatedBook.year
    ? `${updatedBook.author}. ${updatedBook.title}${updatedBook.subtitle ? `: ${updatedBook.subtitle}` : ""}. ${updatedBook.publisher}, ${updatedBook.year}.`
    : "");
  const description = `${expandedDescription(updatedBook)}${libraryBatchSevenDescriptionAddenda[updatedBook.file] ? ` ${libraryBatchSevenDescriptionAddenda[updatedBook.file]}` : ""}`;
  return { ...updatedBook, ...(verifiedPages ? { pages: verifiedPages } : {}), ...(citation ? { citation } : {}), description };
});
